package com.justjava.humanresource.employeeexit.service; import com.justjava.humanresource.employeeexit.entity.*; import com.justjava.humanresource.employeeexit.enums.*; import com.justjava.humanresource.employeeexit.repository.*; import com.justjava.humanresource.hr.entity.*; import com.justjava.humanresource.hr.service.EmployeeDocumentService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class EmployeeExitDocumentService {private final EmployeeExitService exits;private final EmployeeExitDocumentRepository documents;private final EmployeeDocumentService storage;private final EmployeeExitActivityService activity;
 @Transactional public EmployeeExitDocument upload(Long exitId,ExitDocumentType type,ExitDocumentVisibility visibility,MultipartFile file,Long actor){var x=exits.require(exitId);if(file==null||file.isEmpty())throw new IllegalArgumentException("A non-empty document is required.");try{EmployeeDocument stored=storage.uploadDocument(x.getEmployeeId(),"Exit "+type,file);EmployeeExitDocument d=new EmployeeExitDocument();d.setExitCaseId(exitId);d.setDocumentType(type);d.setVisibility(visibility==null?ExitDocumentVisibility.EMPLOYEE_AND_HR:visibility);d.setFileName(file.getOriginalFilename());d.setContentType(file.getContentType());d.setFileSize(file.getSize());d.setStorageReference(String.valueOf(stored.getId()));d.setUploadedByEmployeeId(actor);d.setUploadedAt(LocalDateTime.now());activity.record(exitId,"DOCUMENT_UPLOADED",type+" uploaded",actor,null);return documents.save(d);}catch(IOException e){throw new IllegalStateException("Exit document could not be stored.",e);}}
 @Transactional public EmployeeExitDocument upload(Long exitId,ExitDocumentType type,ExitDocumentVisibility visibility,MultipartFile file,Employee actor,EmployeeExitAuthorizationService authorization){var x=exits.require(exitId);ExitDocumentVisibility effective=visibility==null?ExitDocumentVisibility.EMPLOYEE_AND_HR:visibility;authorization.require(authorization.canUploadDocument(x,actor,effective),"You are not authorized to upload this exit document.");return upload(exitId,type,effective,file,actor.getId());}
 public EmployeeDocument download(Long exitId,Long documentId){EmployeeExitDocument d=documents.findById(documentId).orElseThrow();if(!d.getExitCaseId().equals(exitId))throw new IllegalArgumentException("Document does not belong to this exit.");return storage.getDocumentFile(Long.valueOf(d.getStorageReference()));}
 public EmployeeDocument download(Long exitId,Long documentId,Employee actor,EmployeeExitAuthorizationService authorization){EmployeeExitDocument d=documents.findById(documentId).orElseThrow();var x=exits.require(exitId);if(!d.getExitCaseId().equals(exitId))throw new IllegalArgumentException("Document does not belong to this exit.");authorization.require(authorization.canViewDocument(x,d,actor),"You are not authorized to view this exit document.");return storage.getDocumentFile(Long.valueOf(d.getStorageReference()));}
 @Transactional public void delete(Long exitId,Long documentId,Long actor){EmployeeExitDocument d=documents.findById(documentId).orElseThrow();if(!d.getExitCaseId().equals(exitId))throw new IllegalArgumentException("Document does not belong to this exit.");storage.deleteDocument(Long.valueOf(d.getStorageReference()));documents.delete(d);activity.record(exitId,"DOCUMENT_DELETED",d.getDocumentType()+" deleted",actor,null);}}
